output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "The shopper is obliged to take the cart from the entrance station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "The shopper is prohibited from picking up shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying groceries by hand rather than using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "becomes_hand_carrying": {
          "pre": "hands_free",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_nw_bay",
    "text": "After taking the entrance cart, the shopper is obliged to return it to the northwest cart bay before exiting.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "nw_cart_bay": "at(0,1)",
        "has_cart": "hasCart",
        "cart_parked_nw": "cartAt(0,1)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        },
        "return_cart_nw": {
          "pre": {
            "and": [
              "nw_cart_bay",
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_nw"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_entrance_cart",
      "discharge": "return_cart_nw"
    }
  },
  {
    "id": "leave_cart_only_at_nw_bay",
    "text": "The shopper is prohibited from putting the cart down anywhere except the northwest cart bay.",
    "abstraction": {
      "state_properties": {
        "nw_cart_bay": "at(0,1)",
        "outside_nw_cart_bay": {
          "not": "at(0,1)"
        },
        "has_cart": "hasCart"
      },
      "events": {
        "leave_cart": {
          "pre": {
            "and": [
              "has_cart",
              "LEAVE_CART"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          "outside_nw_cart_bay"
        ]
      }
    }
  },
  {
    "id": "must_drop_cart_when_at_return_bay",
    "text": "Once the shopper reaches the northwest cart bay while pushing the cart, they are prohibited from moving away before leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "nw_cart_bay": "at(0,1)",
        "has_cart": "hasCart",
        "at_bay_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_without_dropping_cart": {
          "pre": {
            "and": [
              "at_bay_with_cart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W",
                  "MOVE"
                ]
              }
            ]
          },
          "post": "has_cart"
        },
        "return_cart_nw": {
          "pre": {
            "and": [
              "at_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_without_dropping_cart"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The shopper is prohibited from exiting unless the cart has been parked at the northwest cart bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_nw": "cartAt(0,1)",
        "cart_not_parked_nw": {
          "not": "cartAt(0,1)"
        },
        "east_exit": "at(9,5)"
      },
      "events": {
        "exit_store": {
          "pre": {
            "and": [
              "east_exit",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_not_parked_nw"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After the cart is parked at the northwest bay, the shopper is prohibited from doing any further shopping interaction.",
    "abstraction": {
      "state_properties": {
        "cart_parked_nw": "cartAt(0,1)",
        "without_cart": {
          "not": "hasCart"
        },
        "post_return_phase": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "post_return_phase",
              "INTERACT"
            ]
          },
          "post": null
        },
        "post_return_item_pickup": {
          "pre": {
            "and": [
              "post_return_phase",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
